INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1001, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, 1, "お！\nあそこに困ってそうな人発見！", 0, "春咲 ひより", 1.4, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1002, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, 1, "大切な人を\n守れるようになりたい…って", 0, "草野 優衣", 1.4, "みんなみたいに\nわたしも強くならなきゃ", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1003, "少しは磨かれると思いますよ。", 0, 1, "キミに必要な集中力と感性が", 0, "士条 怜", 1.4, "フェンシングを始めてみては？", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1004, "みそぎはねぇ、\nかくれんぼやりたい！", 0, 1, "今日はなにして遊ぶ？", 0, "穂高 みそぎ", 1.5, "ねぇ、にいちゃん！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1006, "私といっしょに…\nいかない？", 0, 1, "ねぇ…", 0, "風宮 あかり", 1.4, "風宮あかりです", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1007, "食べ物の恨みは怖いのー", 0, 1, "プリンたべたいのー", 0, "出雲 宮子", 1.5, "出雲宮子なのー", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1008, "いいよ。\n見られることは運命さ…", 0, 1, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, "虹村 雪", 1.4, "ボクは虹村雪。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1009, "人呼んで「疾風の冥姫」!!", 0, 1, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, "柊杏奈", 1.4, "フッ…聞いて後悔するがいい！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1010, "ほんまおおきにやわ～♪", 0, 1, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, "姫宮 真歩", 1.5, "マホマホ王国のプリンセス、\nまほ姫どす", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1011, "ここで会ったが\n100年目～！", 0, 1, "生き別れたお兄ちゃんを探して\n三千世界！", 0, "衣之咲 璃乃", 1.4, "衣之咲璃乃です！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1012, "…って、お願い！\n誰にも言わないでおいて～！", 0, 1, "ち、超能力って…\n何のことかな～？", 0, "柏崎 初音", 1.4, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1016, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, 1, "一応カリスマ読モJKやってまっす！", 0, "美波 鈴奈", 1.4, "ちょす！\n美波鈴奈だよ～♪", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1017, "でも、沖縄もとってもいいとこさー", 0, 1, "東京は遊園地みたいなところさー", 0, "喜屋武 香織", 1.4, "はいたーい。\n喜屋武香織さー。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1018, "イオちゃんって呼んでね。", 0, 1, "先生って呼ばれるのは\nくすぐったいから", 0, "支倉 伊緒", 1.4, "支倉伊緒です。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1020, "ミミをおいてかないでぇ～", 0, 1, "あ！/\お兄ちゃ～ん\nまってよ～", 0, "茜 ミミ", 1.5, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1021, "ふぇぇぇぇぇん……", 0, 1, "あの……\nふぇ……", 0, "栗林 くるみ", 1.5, "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1022, "なんてありがとうございます！", 0, 1, "こんな私に貴重な時間を\n割いていただき、", 0, "風宮 より", 1.4, "風宮よりです。\nあああああ！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1023, "私こっち行きたいー\nね、早く早くー", 0, 1, "おにいちゃんどこいくの？\nえ？", 0, "北条 綾音", 1.5, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1025, "これて何か違う…\nあああすみません！", 0, 1, "ふ、不束者ですが\nどうぞ末永く…って、", 0, "天野 すずめ", 1.4, "わっ…わっ…私、\n天野すずめといいます！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1027, "離しませんわ………\n絶対に…!!", 0, 1, "あなたは…運命の……\n伴侶……", 0, "倉石 恵理子", 1.4, "……クスクス…私は\n…倉石恵理子……", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1028, "…そうでしょ？？", 0, 1, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, "佐々木 咲恋", 1.4, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1029, "あはは、\n私もまだまだだなぁ～", 0, 1, "ぇっと…\nキミ、私のこと知らないの?!", 0, "桜井 望", 1.4, "桜井望だよ！\nよろしくねっ", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1030, "ショーグン、\nワタシと一緒に天下統一デース！", 0, 1, "初めまして、\n私はニノン・ジュベール申すデス！", 0, "ニノン・ジュベール", 1.4, "デケデケデンっ！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1031, "おかしいですね……", 0, 1, "でもって私の隣にいるのが……\nえ、見えない？", 0, "上喜 しのぶ", 1.4, "上喜しのぶです。\n手元のドクロが父です。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1033, "そう、\nオラのボケに突っ込める相方が…！", 0, 1, "けんども\nそれには足りないモンが…", 0, "野戸まひる", 1.5, "目指すはビッグな\nお笑い芸人だっぺ！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1034, "ちょ\nちょっと一杯飲んできます…！", 0, 1, "ちょっと緊張しちゃって…", 0, "綾瀬 ゆかり", 1.4, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1036, "これ以上お話しすることは…\nないです！", 0, 1, "知らない人とは話しちゃいけないので", 0, "氷川 鏡華", 1.5, "氷川鏡華…です", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1038, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, 1, "……あ、アラーム。", 0, "柏崎 栞", 1.4, "柏崎…栞です。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1040, "野に咲く花が、\n唯一の話相手です。", 0, 1, "私、一人も友達がいなくて……", 0, "双葉 碧", 1.4, "ふ、双葉碧です。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1042, "そう思っています。", 0, 1, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, "三角 千歌", 1.4, "三角千歌です。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1043, "う、疑ってすまなかったな…", 0, 1, "あぁ？\nお前のそいつの仲間か？", 0, "安芸 真琴", 1.4, "安芸真琴だ。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1044, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, 1, "生けとし生ける全ての者よ！", 0, "イリヤ・オーンスタイン", 1.4, "わらわこそは夜を総べる者！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1045, "ｌク、クウカに何かご用ですか!?", 0, 1, "ぐふふふふ……はっ！", 0, "遠見 空花", 1.4, "そこで騎士は妖精を乱暴に……", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1046, "う～ん…\n猫ってホントに最高にゃ～♪", 0, 1, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, "宮坂たまき", 1.4, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1048, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, 1, "それでは早速クエストに…", 0, "大神 美冬", 1.4, "大神美冬よ！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1049, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, 1, "クエストもバトルも\n掃除も洗濯も", 0, "星野静流", 1.4, "星野静流だよ！", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1050, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, 1, "見ての通りの\nセクシー美少女で", 0, "玉泉美咲", 1.5, "アタシは玉泉美咲。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1052, "？？？？", 0, 1, "？？？？", 0, "リマ", 1.4, "？？？", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1053, "そ、そこまでいうなら\nもらってやる", 0, 1, "菓子でつろうなどと\n稚拙な策を……", 0, "モニカ・ヴァイスヴィント", 1.5, "モニカ・ヴァイスヴィントだ。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1058, "そ、そこまでいうなら\nもらってやる", 0, 1, "菓子でつろうなどと\n稚拙な策を……", 0, "ペコリーヌ", 1.5, "モニカ・ヴァイスヴィントだ。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1059, "そ、そこまでいうなら\nもらってやる", 0, 1, "菓子でつろうなどと\n稚拙な策を……", 0, "コッコロ", 1.5, "モニカ・ヴァイスヴィントだ。", 0, 1, 1, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1060, "そ、そこまでいうなら\nもらってやる", 0, 1, "菓子でつろうなどと\n稚拙な策を……", 0, "キャル", 1.5, "モニカ・ヴァイスヴィントだ。", 0, 1, 1, 0);
